<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/../includes/expenses.php';
require_once __DIR__.'/../includes/record_actions.php';
$user=require_business(); $connection=db(); $page_title='Expenses'; $active_page='expenses'; $dashboard_layout=true;
$error=null; $data=null; $notice=take_flash();
try { $filters=expense_filters($_GET); } catch (InvalidArgumentException $exception) { http_response_code(400); $error=$exception->getMessage().' Showing default filters.'; $filters=expense_filters([]); }
try {
    $connection->beginTransaction(); $catalog=expense_catalog($connection,(int)$user['business_id']);
    try { $data=expense_list($connection,(int)$user['business_id'],$filters); } catch (InvalidArgumentException $exception) { http_response_code(400); $error=$exception->getMessage().' Showing default filters.'; $filters=expense_filters([]); $data=expense_list($connection,(int)$user['business_id'],$filters); }
    $schedules=expense_query($connection,'SELECT r.*,c.category_name FROM recurring_expenses r JOIN expense_categories c ON c.expense_category_id=r.expense_category_id AND c.business_id=r.business_id WHERE r.business_id=? ORDER BY r.is_active DESC,r.next_due_date,r.recurring_expense_id',[$user['business_id']])->fetchAll();
    $connection->commit();
} catch (Throwable $exception) { if ($connection->inTransaction()) { $connection->rollBack(); } error_log('ProfitPocket: expenses list failed.'); http_response_code(503); $error='Expenses are temporarily unavailable. Please try again.'; }
$period=$filters['period']; $action_url=app_url('user/expense_action.php');
require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/navbar.php';
?>
<main class="dashboard-main" id="dashboard-content">
    <div class="dashboard-heading"><div><h1>Expenses</h1><p>Track and manage your business expenses.</p></div><a class="btn btn-primary btn-sm" data-expense-modal="create" href="<?= e($action_url.'?action=create') ?>"><?= dashboard_icon('plus-lg') ?> Add Expense</a></div>
    <div id="expense-feedback" class="alert d-none" role="status" tabindex="-1"></div>
    <?php if ($notice): ?><div class="alert alert-success" role="status"><?= e($notice) ?></div><?php endif; ?>
    <?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
    <?php if ($data): ?>
    <section class="dashboard-panel filter-panel"><form class="dashboard-filter expense-filter" method="get" action="<?= e(app_url('user/expenses.php')) ?>">
        <div class="search-control"><label for="q">Search expenses</label><input class="form-control form-control-sm" type="search" id="q" name="q" maxlength="100" value="<?= e($filters['q']) ?>" placeholder="Description or category"></div>
        <div class="period-controls"><label for="period">Period</label><select class="form-select form-select-sm" id="period" name="period"><?php foreach (['today'=>'Today','week'=>'This week','month'=>'This month','custom'=>'Custom range'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $period['choice']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
        <div class="date-controls" id="custom-dates"><div><label for="start">From</label><input class="form-control form-control-sm" type="date" id="start" name="start" value="<?= e($period['start']->format('Y-m-d')) ?>"></div><div><label for="end">To</label><input class="form-control form-control-sm" type="date" id="end" name="end" value="<?= e($period['end']->format('Y-m-d')) ?>"></div></div>
        <div><label for="category">Category</label><select class="form-select form-select-sm" id="category" name="category"><option value="">All categories</option><?php foreach ($catalog['categories'] as $category): ?><option value="<?= e($category['expense_category_id']) ?>" <?= (string)$filters['category']===(string)$category['expense_category_id']?'selected':'' ?>><?= e($category['category_name']) ?></option><?php endforeach; ?></select></div>
        <div><label for="state">Status</label><select class="form-select form-select-sm" id="state" name="state"><?php foreach (['posted'=>'Recorded','void'=>'Voided','all'=>'All records'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $filters['state']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
        <div><label for="treatment">Type</label><select class="form-select form-select-sm" id="treatment" name="treatment"><?php foreach (['operating'=>'Operating expenses','inventory_purchase'=>'Stock purchases','other_cash_outflow'=>'Other cash payments','all'=>'All types'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $filters['treatment']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
        <div><label for="sort">Date order</label><select class="form-select form-select-sm" id="sort" name="sort"><option value="newest" <?= $filters['sort']==='newest'?'selected':'' ?>>Newest first</option><option value="oldest" <?= $filters['sort']==='oldest'?'selected':'' ?>>Oldest first</option></select></div>
        <button class="btn btn-primary btn-sm" type="submit">Apply</button><a class="sales-reset" href="<?= e(app_url('user/expenses.php')) ?>">Reset</a>
    </form></section>
    <section class="summary-grid expense-summary" aria-label="Expense summary">
        <article class="summary-card"><div class="summary-label"><h2>Total Expenses</h2></div><p class="summary-amount"><?= e(sale_money($data['summary']['total'])) ?></p><p class="summary-description">Operating expenses · selected filters</p></article>
        <article class="summary-card"><div class="summary-label"><h2>Expenses This Month</h2></div><p class="summary-amount"><?= e(sale_money($data['month'])) ?></p><p class="summary-description">Operating expenses · <?= e(date('F Y')) ?>, all categories</p></article>
        <article class="summary-card"><div class="summary-label"><h2>Highest Expense Category</h2></div><p class="expense-top-category"><?= e($data['highest']['category_name']??'No expenses yet') ?></p><p class="expense-category-amount"><?= e(sale_money($data['highest']['amount']??'0.00')) ?></p><p class="summary-description">Operating expenses · selected filters</p></article>
    </section>
    <section class="dashboard-panel expense-history"><div class="panel-heading"><div><h2>Expense history</h2><p><?= e($period['label']) ?> · <?= e($data['summary']['records']) ?> matching records</p></div><a class="sales-text-link" data-expense-modal="category" href="<?= e($action_url.'?action=category') ?>">Add category</a></div>
        <?php if ($data['rows']): ?><table class="table transactions-table expense-table mb-0"><caption class="visually-hidden">Expense history for <?= e($user['business_name']) ?></caption><thead><tr><th scope="col">Date</th><th scope="col">Expense category</th><th scope="col">Description</th><th scope="col" class="text-end">Amount</th><th scope="col">Payment method</th><th scope="col">Actions</th></tr></thead><tbody>
        <?php foreach ($data['rows'] as $expense): ?><tr>
            <td data-label="Date" class="transaction-date"><?= e((new DateTimeImmutable($expense['expense_date']))->format('j M Y')) ?></td><td data-label="Category"><?= e($expense['category_name']) ?></td><td data-label="Description" class="expense-description"><?= e($expense['description']) ?><?php if ($expense['expense_status']==='void'): ?><span class="transaction-context">Voided</span><?php endif; ?><?php if ($expense['expense_treatment']!=='operating'): ?><span class="transaction-context"><?= $expense['expense_treatment']==='inventory_purchase'?'Stock purchase':'Other cash payment' ?></span><?php endif; ?></td><td data-label="Amount" class="text-end transaction-amount"><?= e(sale_money($expense['amount'])) ?></td><td data-label="Payment method"><?= e($expense['method_name']) ?></td>
            <td class="expense-actions"><?php $expenseActions=[]; if ($expense['expense_status']==='posted') { $expenseActions=[['edit','Edit details',$action_url.'?action=edit&id='.$expense['expense_id'],false],['void','Void expense',$action_url.'?action=void&id='.$expense['expense_id'],true]]; } record_actions('expense',$expense['description'],$action_url.'?action=details&id='.$expense['expense_id'],$expenseActions); ?></td>
        </tr><?php endforeach; ?></tbody></table>
        <nav class="sales-pagination" aria-label="Expense pages"><span>Page <?= e($data['page']) ?> of <?= e($data['pages']) ?></span><div><?php foreach (['Previous'=>$data['page']-1,'Next'=>$data['page']+1] as $label=>$target): ?><?php if ($target>=1 && $target<=$data['pages']): $params=$_GET; $params['page']=$target; ?><a class="btn btn-outline-secondary btn-sm" href="<?= e(app_url('user/expenses.php').'?'.http_build_query($params)) ?>"><?= e($label) ?></a><?php else: ?><button class="btn btn-outline-secondary btn-sm" disabled><?= e($label) ?></button><?php endif; ?><?php endforeach; ?></div></nav>
        <?php else: ?><div class="empty-state"><h3>No expenses match these filters</h3><p>Try another date or record an expense when your business makes a payment.</p><a class="btn btn-primary btn-sm mt-3" data-expense-modal="create" href="<?= e($action_url.'?action=create') ?>">Add Expense</a></div><?php endif; ?>
        <div class="table-footnote">Totals show operating expenses only. Stock purchases are excluded so product costs are not counted twice. Voided records remain in history.</div>
    </section>
    <details class="dashboard-panel expense-schedules"><summary>Recurring expenses <span>Schedules do not affect totals until a payment is recorded.</span></summary><div class="expense-schedule-content"><a class="btn btn-outline-secondary btn-sm mb-3" data-expense-modal="schedule" href="<?= e($action_url.'?action=schedule') ?>">New recurring schedule</a>
        <?php if (!$schedules): ?><p class="sale-modal-note">No recurring schedules yet. Use this for regular payments such as rent or internet.</p><?php endif; ?>
        <?php foreach ($schedules as $schedule): ?><article class="expense-schedule-row"><div><h3><?= e($schedule['description']) ?></h3><p><?= e($schedule['category_name']) ?> · <?= e(sale_money($schedule['amount'])) ?> · Every <?= e($schedule['repeat_every']) ?> <?= e(['daily'=>'day(s)','weekly'=>'week(s)','monthly'=>'month(s)','yearly'=>'year(s)'][$schedule['frequency']]) ?></p><p><?= $schedule['is_active']?'Next due':'Paused · next due' ?> <?= e($schedule['next_due_date']) ?><?= $schedule['end_date']?' · Ends '.e($schedule['end_date']):'' ?></p></div><div class="expense-schedule-actions"><?php if ($schedule['is_active'] && $schedule['next_due_date']<=date('Y-m-d') && (!$schedule['end_date'] || $schedule['next_due_date']<=$schedule['end_date'])): ?><a class="btn btn-primary btn-sm" data-expense-modal="confirm" href="<?= e($action_url.'?action=confirm&id='.$schedule['recurring_expense_id']) ?>">Record paid expense</a><?php endif; ?><a class="btn btn-outline-secondary btn-sm" data-expense-modal="toggle" href="<?= e($action_url.'?action=toggle&id='.$schedule['recurring_expense_id']) ?>"><?= $schedule['is_active']?'Pause':'Resume' ?></a></div></article><?php endforeach; ?>
    </div></details>
    <?php endif; ?>
</main>
<div class="modal" id="expense-action-modal" tabindex="-1" aria-labelledby="expense-modal-title" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable modal-fullscreen-sm-down"><div class="modal-content"></div></div></div>
